import { describe, expect, it } from "vitest";
import { Parser, type Op } from "../src/parser.js";

const LIMITS = { maxControlLine: 64, maxPayload: 32 };

function parseSplit(input: Buffer, cuts: number[]): Op[] {
  const ops: Op[] = [];
  const p = new Parser(LIMITS, (op) => ops.push(op));
  let at = 0;
  for (const c of [...cuts, input.length]) {
    p.feed(input.subarray(at, c));
    at = c;
  }
  return ops;
}

it("same ops at every split offset", () => {
  const stream = Buffer.from('CONNECT {"verbose":false}\r\nSUB a.b 1\r\nPUB a.b r 7\r\nab\r\ncde\r\nPING\r\nUNSUB 1 3\r\n');
  const expected = parseSplit(stream, []);
  expect(expected).toHaveLength(5);
  for (let cut = 1; cut < stream.length; cut++) {
    expect(parseSplit(stream, [cut]), `cut at ${cut}`).toEqual(expected);
  }
});

